using System.Text.Json;
using Domain.Abstractions.Entities;

namespace Domain.Entities.Books
{
    /// <summary>
    /// Editor page owned by <see cref="Book"/>. The id is generated by the client
    /// (cuid/uuid); <see cref="Version"/> is the optimistic-concurrency token.
    /// </summary>
    public class BookPage : BaseEntity<string>
    {
        public Guid BookId { get; private set; }
        public int Position { get; private set; }
        public string Content { get; private set; } = string.Empty;
        public int Version { get; private set; }
        public int SchemaVersion { get; private set; } = 2;
        public DateTimeOffset UpdatedAt { get; private set; }

        private BookPage()
        {
        }

        public BookPage(string pageId, Guid bookId, int position, string content, int version = 1)
        {
            Id = pageId;
            BookId = bookId;
            Position = position;
            Content = content;
            Version = version;
            SchemaVersion = ReadSchemaVersion(content);
            UpdatedAt = DateTimeOffset.UtcNow;
        }

        public void Update(int position, string content)
        {
            Position = position;
            Content = content;
            SchemaVersion = ReadSchemaVersion(content);
            Version++;
            UpdatedAt = DateTimeOffset.UtcNow;
        }

        public void SetPosition(int position) => Position = position;

        private static int ReadSchemaVersion(string content)
        {
            try
            {
                using var document = JsonDocument.Parse(content);
                return document.RootElement.TryGetProperty("schemaVersion", out var value) &&
                       value.TryGetInt32(out var schemaVersion) &&
                       schemaVersion > 0
                    ? schemaVersion
                    : 2;
            }
            catch (JsonException)
            {
                return 2;
            }
        }
    }
}
